@Component("approval-handler")
@ProcessingGroup("approval-processing-group")
public class ApprovalEventHandler {
	
	// core constructor
	ApprovalEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateApprovalEvent
     */
    @EventHandler
    public void handle( CreateApprovalEvent event) {
        entityManager.persist(new Approval(event.getApprovalId(), event.getApproverComment(), event.getActionDate(), event.getApprover(), event.getTimesheet(), event.getLeaveRequest(), event.getStatus()));
    }

    /*
     * @param	event UpdateApprovalEvent
     */
    @EventHandler
    public Approval handle( UpdateApprovalEvent event) {
    	entityManager.merge(new Approval(event.getApprovalId(), event.getApproverComment(), event.getActionDate(), event.getApprover(), event.getTimesheet(), event.getLeaveRequest(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteApprovalEvent
     */
    @EventHandler
    public void on( DeleteApprovalEvent event) {
    	Approval entity = new Approval();
   
    	// ------------------------------------------
    	// apply the ApprovalId
    	// ------------------------------------------
    	entity.setApprovalId( event.getApprovalId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ApprovalRepository approvalEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ApprovalEventHandler.class.getName());

}
